const n = 1000;
// Without hoisting: k recomputed every iteration.
let evalsNaive = 0;
for (let i = 0; i < n; i++) {
  const k = (10 * 2); evalsNaive++; // pure invariant, recomputed
  void (i + k);
}
// With scheduler hoisting: k computed once before the loop.
let evalsHoisted = 0;
const kOnce = (10 * 2); evalsHoisted++;
for (let i = 0; i < n; i++) {
  void (i + kOnce);
}
console.log('naive=' + evalsNaive + ' hoisted=' + evalsHoisted + ' saved=' + (evalsNaive - evalsHoisted));
